INSERT INTO `pages` (`slug`, `content`) VALUES ('terroir', '{"heading":{"eyebrow":{"en":"Our vineyards / Kakheti, Georgia","ka":""},"title":{"en":"A place\nlike no other.","ka":""},"subtitle":{"en":"Every soil, every slope, every season.\nA different voice in the glass.","ka":""}},"cover":{"image":"/images/vineyard.webp","caption":{"en":"Alazani Valley / Kakheti","ka":""}},"intro":{"eyebrow":{"en":"The character of Kakheti","ka":""},"heading":{"en":"One region.\nMany expressions.","ka":""},"body":{"en":"Our vineyards extend across Kakheti, with holdings of up to 500 hectares. Changing altitudes, soils and microclimates create a rich range of expressions from Georgia’s native grapes.","ka":""}},"listHeading":{"label":{"en":"Selected locations","ka":""},"subtitle":{"en":"The soil. The grape. The character.","ka":""}},"places":[{"name":{"en":"Alaverdi","ka":""},"grape":{"en":"Saperavi","ka":""},"text":{"en":"Alluvial soils and yellow clay in a landscape shaped by the Alazani Valley.","ka":""},"image":"/images/vineyards/alaverdi.webp"},{"name":{"en":"Mukuzani","ka":""},"grape":{"en":"Saperavi","ka":""},"text":{"en":"Gravel and red clay bring their character to deeply expressive dry red wines.","ka":""},"image":"/images/vineyards/mukuzani.webp"},{"name":{"en":"Maghraani","ka":""},"grape":{"en":"Kisi · Saperavi","ka":""},"text":{"en":"Forest-derived soils and rich biodiversity give this place a distinctive voice.","ka":""},"image":"/images/vineyards/maghraani.webp"},{"name":{"en":"Tsinandali","ka":""},"grape":{"en":"Rkatsiteli","ka":""},"text":{"en":"The limestone and clay soils of Akura are home to vineyards for dry white wines.","ka":""},"image":"/images/vineyards/tsinandali.webp"}],"closing":{"image":"/images/vineyard.webp","eyebrow":{"en":"From the land to the glass","ka":""},"heading":{"en":"Take a little\nGeorgia with you.","ka":""}}}');
